export class TestCase{successes=[];failures={};activeTestFn;assertionIndex=0;constructor(){"function"==typeof this?.setUp&&this.setUp(),this.test()}async test(){for(const t of this.#t(this)){this.activeTestFn=t,this.assertionIndex=0;let s=null;"function"==typeof this?.globalProvider&&(s=this.globalProvider()),await this[t](s)}console.log(JSON.stringify({successes:this.successes,failures:this.failures})),"function"==typeof this?.tearDown&&this?.tearDown()}#t(t){let s=Object.getOwnPropertyNames(Object.getPrototypeOf(t));return s=s.filter(t=>t.startsWith("test")),s.filter(t=>"function"==typeof this[t])}#s(){return`${this.activeTestFn}#${this.assertionIndex++}`}fail(t="UNKNOWN - If invoking AkriTestCase.fail yourself, always add a message"){this.failures[this.#s()]=t instanceof Error?t?.stack:new Error(t)?.stack}ok(){this.successes.push(this.#s())}assertEquals(t,s){try{if(t!==s)return this.fail(new Error(`Failed to assert that actual '${t}' equals expected '${s}'`))}catch(t){return this.fail(t)}this.ok()}assertTrue(t){this.assertEquals(t,!0)}assertFalse(t){this.assertEquals(t,!1)}async assertThrows(t,s=null){if("function"!=typeof t)return this.fail('Argument "fn" must be a callback');try{await t(),this.fail(new Error("Failed to assert that this test throws an exception"))}catch(t){return null!==s&&t.message!==s?this.fail(new Error(`Failed to assert that exception '${t}' matches expected exception '${s}'`)):this.ok()}}}